ALTER TABLE opportunity_collaboration_work_packages ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE opportunity_collaboration_work_packages ADD COLUMN IF NOT EXISTS deleted_by bigint REFERENCES users(id);
ALTER TABLE opportunity_collaboration_work_package_versions DROP CONSTRAINT IF EXISTS opportunity_collaboration_work_package_versions_status_check;
ALTER TABLE opportunity_collaboration_work_package_versions DROP CONSTRAINT IF EXISTS opportunity_collaboration_work_package_versions_check;
ALTER TABLE opportunity_collaboration_work_package_versions ADD CONSTRAINT opportunity_collaboration_work_package_versions_status_check CHECK(status IN ('submitted','returned','accepted','withdrawn'));
ALTER TABLE opportunity_collaboration_work_package_versions ADD CONSTRAINT opportunity_collaboration_work_package_versions_check CHECK((status IN ('submitted','withdrawn') AND reviewed_by_user_id IS NULL AND reviewed_at IS NULL) OR(status IN ('returned','accepted') AND reviewed_by_user_id IS NOT NULL AND reviewed_at IS NOT NULL));
ALTER TABLE opportunity_collaboration_work_package_events DROP CONSTRAINT IF EXISTS opportunity_collaboration_work_package_events_event_type_check;
ALTER TABLE opportunity_collaboration_work_package_events ADD CONSTRAINT opportunity_collaboration_work_package_events_event_type_check CHECK(event_type IN ('created','submitted','returned','accepted','updated','withdrawn','deleted','file_retired'));
CREATE TABLE IF NOT EXISTS opportunity_technical_team_assignments(opportunity_id bigint NOT NULL REFERENCES opportunities(id),user_id bigint NOT NULL REFERENCES users(id),position text NOT NULL CHECK(position IN ('lead','support')),specialty text NOT NULL DEFAULT '',is_active boolean NOT NULL DEFAULT true,updated_by bigint NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(opportunity_id,user_id));
CREATE TABLE IF NOT EXISTS opportunity_technical_team_events(id bigserial PRIMARY KEY,opportunity_id bigint NOT NULL REFERENCES opportunities(id),actor_user_id bigint NOT NULL REFERENCES users(id),before_state jsonb NOT NULL,after_state jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
